```html
<!doctype html>
<html>
<head>
    <style>
        body {
            margin: 0;
            padding: 0;
            overflow: hidden;
            background: #1a1a1a;
            font-family: Arial, sans-serif;
            touch-action: none;
        }
        #game-container {
            position: relative;
            width: 100vw;
            height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
        }
        #game-canvas {
            background: #000;
            display: block;
            max-width: 1280px;
            max-height: 960px;
        }
        #ui {
            position: absolute;
            top: 10px;
            left: 10px;
            color: white;
            font-size: 16px;
            z-index: 100;
        }
        #controls {
            position: absolute;
            bottom: 20px;
            left: 20px;
            color: white;
            font-size: 14px;
            z-index: 100;
        }
        #restart-btn {
            position: absolute;
            bottom: 20px;
            right: 20px;
            padding: 8px 16px;
            background: rgba(0,0,0,0.7);
            color: white;
            border: 1px solid #444;
            border-radius: 4px;
            cursor: pointer;
            z-index: 100;
        }
        #restart-btn:hover {
            background: rgba(0,0,0,0.9);
        }
        #game-over {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: rgba(0,0,0,0.9);
            color: white;
            padding: 20px;
            border-radius: 10px;
            text-align: center;
            display: none;
            z-index: 200;
        }
        #win-message {
            color: gold;
            font-size: 24px;
            margin-bottom: 10px;
        }
        #loss-message {
            color: red;
            font-size: 24px;
            margin-bottom: 10px;
        }
    </style>
</head>
<body>
    <div id="game-container">
        <canvas id="game-canvas"></canvas>
        <div id="ui">
            <div>Fireboy Diamonds: <span id="fb-diamonds">0</span>/8</div>
            <div>Watergirl Diamonds: <span id="wg-diamonds">0</span>/8</div>
        </div>
        <div id="controls">
            Fireboy: ← → ↑<br>
            Watergirl: A D W (or Shift/CapsLock)
        </div>
        <button id="restart-btn">Restart</button>
        <div id="game-over">
            <div id="win-message">You Win!</div>
            <div id="loss-message">Game Over</div>
            <button id="restart-game">Restart</button>
        </div>
    </div>

    <script>
        const canvas = document.getElementById('game-canvas');
        const ctx = canvas.getContext('2d');
        const restartBtn = document.getElementById('restart-btn');
        const restartGameBtn = document.getElementById('restart-game');
        const gameOverDiv = document.getElementById('game-over');
        const fbDiamonds = document.getElementById('fb-diamonds');
        const wgDiamonds = document.getElementById('wg-diamonds');

        // Game state
        let state = {
            fireboy: { x: 100, y: 700, width: 20, height: 30, speed: 5, jumpForce: 12, velocityY: 0, onGround: false, alive: true },
            watergirl: { x: 120, y: 700, width: 20, height: 30, speed: 5, jumpForce: 12, velocityY: 0, onGround: false, alive: true },
            diamonds: {
                fb: [
                    { x: 350, y: 650, width: 15, height: 15, collected: false },
                    { x: 450, y: 650, width: 15, height: 15, collected: false },
                    { x: 650, y: 550, width: 15, height: 15, collected: false },
                    { x: 850, y: 550, width: 15, height: 15, collected: false },
                    { x: 1000, y: 450, width: 15, height: 15, collected: false },
                    { x: 1100, y: 450, width: 15, height: 15, collected: false },
                    { x: 350, y: 300, width: 15, height: 15, collected: false },
                    { x: 800, y: 300, width: 15, height: 15, collected: false }
                ],
                wg: [
                    { x: 450, y: 650, width: 15, height: 15, collected: false },
                    { x: 650, y: 650, width: 15, height: 15, collected: false },
                    { x: 350, y: 550, width: 15, height: 15, collected: false },
                    { x: 850, y: 550, width: 15, height: 15, collected: false },
                    { x: 1000, y: 450, width: 15, height: 15, collected: false },
                    { x: 1100, y: 450, width: 15, height: 15, collected: false },
                    { x: 500, y: 300, width: 15, height: 15, collected: false },
                    { x: 900, y: 300, width: 15, height: 15, collected: false }
                ]
            },
            platforms: [
                { x: 0, y: 800, width: 1280, height: 50, type: 'floor' },
                { x: 200, y: 600, width: 500, height: 30, type: 'floor' },
                { x: 500, y: 500, width: 300, height: 20, type: 'floor' },
                { x: 800, y: 400, width: 300, height: 20, type: 'floor' },
                { x: 1000, y: 300, width: 200, height: 20, type: 'floor' },
                { x: 1200, y: 200, width: 80, height: 20, type: 'floor' },
                { x: 1100, y: 350, width: 100, height: 100, type: 'tilting', angle: 0, pivotX: 1150, pivotY: 350 },
                { x: 500, y: 200, width: 100, height: 100, type: 'tilting', angle: 0, pivotX: 550, pivotY: 200 },
                { x: 500, y: 400, width: 300, height: 100, type: 'moving', direction: 1, speed: 2, offset: 0 },
                { x: 400, y: 200, width: 300, height: 20, type: 'moving', direction: 1, speed: 2, offset: 0 }
            ],
            movingBarrier: {
                x: 600, y: 300, width: 50, height: 200, open: false, targetOpen: false
            },
            pressurePlates: [
                { x: 200, y: 570, width: 100, height: 10, type: 'lower', active: false },
                { x: 1000, y: 570, width: 100, height: 10, type: 'lower', active: false },
                { x: 400, y: 180, width: 100, height: 10, type: 'upper', active: false },
                { x: 800, y: 180, width: 100, height: 10, type: 'upper', active: false }
            ],
            poisonPools: [
                { x: 300, y: 620, width: 150, height: 50, type: 'green' },
                { x: 900, y: 620, width: 150, height: 50, type: 'green' },
                { x: 400, y: 250, width: 150, height: 50, type: 'green' },
                { x: 700, y: 250, width: 150, height: 50, type: 'green' }
            ],
            lavaPools: [
                { x: 300, y: 500, width: 150, height: 50, type: 'lava' },
                { x: 900, y: 500, width: 150, height: 50, type: 'lava' }
            ],
            waterPools: [
                { x: 300, y: 620, width: 150, height: 50, type: 'water' },
                { x: 900, y: 620, width: 150, height: 50, type: 'water' }
            ],
            exits: [
                { x: 100, y: 100, width: 30, height: 30, type: 'fireboy' },
                { x: 1150, y: 100, width: 30, height: 30, type: 'watergirl' }
            ],
            gameOver: false,
            win: false
        };

        // Resize canvas to fit viewport
        function resizeCanvas() {
            const container = document.getElementById('game-container');
            const containerWidth = container.clientWidth;
            const containerHeight = container.clientHeight;
            const ratio = 1280 / 960;

            if (containerWidth / containerHeight > ratio) {
                canvas.width = containerHeight * ratio;
                canvas.height = containerHeight;
            } else {
                canvas.width = containerWidth;
                canvas.height = containerWidth / ratio;
            }

            // Scale factor for drawing
            state.scale = Math.min(containerWidth / 1280, containerHeight / 960);
        }

        // Draw functions
        function drawPlatform(platform) {
            ctx.fillStyle = '#5a4a3a';
            ctx.fillRect(platform.x * state.scale, platform.y * state.scale, platform.width * state.scale, platform.height * state.scale);

            if (platform.type === 'moving') {
                const offsetX = platform.offset;
                ctx.fillStyle = '#7a6a4a';
                ctx.fillRect((platform.x + offsetX) * state.scale, platform.y * state.scale, platform.width * state.scale, platform.height * state.scale);
            }
        }

        function drawMovingBarrier() {
            ctx.fillStyle = '#3a3a3a';
            if (state.movingBarrier.open) {
                ctx.fillRect(state.movingBarrier.x * state.scale, state.movingBarrier.y * state.scale, state.movingBarrier.width * state.scale, state.movingBarrier.height * state.scale);
            } else {
                // Draw as closed barrier
                ctx.fillRect(state.movingBarrier.x * state.scale, state.movingBarrier.y * state.scale, 50 * state.scale, 10 * state.scale);
                ctx.fillRect(state.movingBarrier.x * state.scale, (state.movingBarrier.y + state.movingBarrier.height - 10) * state.scale, 50 * state.scale, 10 * state.scale);
                ctx.fillRect(state.movingBarrier.x * state.scale, state.movingBarrier.y * state.scale, 10 * state.scale, state.movingBarrier.height * state.scale);
                ctx.fillRect((state.movingBarrier.x + state.movingBarrier.width - 10) * state.scale, state.movingBarrier.y * state.scale, 10 * state.scale, state.movingBarrier.height * state.scale);
            }
        }

        function drawPressurePlate(plate) {
            ctx.fillStyle = plate.active ? '#7a7a7a' : '#5a5a5a';
            ctx.fillRect(plate.x * state.scale, plate.y * state.scale, plate.width * state.scale, plate.height * state.scale);
        }

        function drawPool(pool) {
            if (pool.type === 'green') {
                ctx.fillStyle = '#00ff00';
            } else if (pool.type === 'lava') {
                ctx.fillStyle = '#ff0000';
            } else if (pool.type === 'water') {
                ctx.fillStyle = '#0000ff';
            }
            ctx.fillRect(pool.x * state.scale, pool.y * state.scale, pool.width * state.scale, pool.height * state.scale);
        }

        function drawDiamond(diamond, color) {
            if (!diamond.collected) {
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.moveTo(diamond.x * state.scale, (diamond.y - 10) * state.scale);
                ctx.lineTo((diamond.x + 7) * state.scale, (diamond.y + 5) * state.scale);
                ctx.lineTo((diamond.x + 15) * state.scale, (diamond.y - 10) * state.scale);
                ctx.lineTo((diamond.x + 7) * state.scale, (diamond.y - 20) * state.scale);
                ctx.lineTo(diamond.x * state.scale, (diamond.y + 5) * state.scale);
                ctx.lineTo((diamond.x + 8) * state.scale, (diamond.y - 5) * state.scale);
                ctx.closePath();
                ctx.fill();
            }
        }

        function drawExit(exit) {
            ctx.fillStyle = exit.type === 'fireboy' ? '#ff4500' : '#0064ff';
            ctx.beginPath();
            ctx.moveTo(exit.x * state.scale, (exit.y - 10) * state.scale);
            ctx.lineTo((exit.x + 10) * state.scale, (exit.y + 5) * state.scale);
            ctx.lineTo((exit.x + 20) * state.scale, (exit.y - 10) * state.scale);
            ctx.lineTo((exit.x + 10) * state.scale, (exit.y - 20) * state.scale);
            ctx.lineTo(exit.x * state.scale, (exit.y + 5) * state.scale);
            ctx.lineTo((exit.x + 10) * state.scale, (exit.y - 5) * state.scale);
            ctx.closePath();
            ctx.fill();
        }

        function drawCharacter(char, color) {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.arc(char.x * state.scale + char.width/2 * state.scale, (char.y + char.height) * state.scale, char.width/2 * state.scale, 0, Math.PI * 2);
            ctx.fill();

            // Head
            ctx.fillStyle = '#ffcc00';
            ctx.beginPath();
            ctx.arc(char.x * state.scale + char.width/2 * state.scale, (char.y + char.height - 10) * state.scale, char.width/2 * state.scale, 0, Math.PI * 2);
            ctx.fill();

            // Eyes
            ctx.fillStyle = '#000';
            ctx.fillRect((char.x + char.width/4) * state.scale, (char.y + char.height - 15) * state.scale, 5 * state.scale, 5 * state.scale);
            ctx.fillRect((char.x + 3*char.width/4) * state.scale, (char.y + char.height - 15) * state.scale, 5 * state.scale, 5 * state.scale);

            // Mouth
            ctx.fillStyle = '#ff0000';
            ctx.fillRect((char.x + char.width/2 - 5) * state.scale, (char.y + char.height - 5) * state.scale, 10 * state.scale, 3 * state.scale);
        }

        function drawTiltingPlatform(platform) {
            ctx.save();
            ctx.translate((platform.x + platform.width/2) * state.scale, (platform.y + platform.height/2) * state.scale);
            ctx.rotate(platform.angle * Math.PI / 180);

            ctx.fillStyle = '#5a4a3a';
            ctx.fillRect(
                (-(platform.width/2)) * state.scale,
                (-(platform.height/2)) * state.scale,
                platform.width * state.scale,
                platform.height * state.scale
            );

            ctx.restore();
        }

        function drawGame() {
            // Clear canvas
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw background
            ctx.fillStyle = '#2a2a1a';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw temple walls
            ctx.fillStyle = '#3a3a2a';
            ctx.fillRect(0, 0, canvas.width, 50 * state.scale);
            ctx.fillRect(0, (850) * state.scale, canvas.width, 50 * state.scale);

            // Draw columns
            ctx.fillStyle = '#5a4a3a';
            for (let i = 0; i < 5; i++) {
                ctx.fillRect((100 + i * 200) * state.scale, 200 * state.scale, 30 * state.scale, 600 * state.scale);
            }

            // Draw platforms
            state.platforms.forEach(platform => {
                if (platform.type === 'tilting') {
                    drawTiltingPlatform(platform);
                } else if (platform.type === 'moving') {
                    drawPlatform(platform);
                } else {
                    drawPlatform(platform);
                }
            });

            // Draw moving barrier
            drawMovingBarrier();

            // Draw pressure plates
            state.pressurePlates.forEach(plate => {
                drawPressurePlate(plate);
            });

            // Draw pools
            state.poisonPools.forEach(pool => drawPool(pool));
            state.lavaPools.forEach(pool => drawPool(pool));
            state.waterPools.forEach(pool => drawPool(pool));

            // Draw diamonds
            state.diamonds.fb.forEach(diamond => drawDiamond(diamond, '#ff4500'));
            state.diamonds.wg.forEach(diamond => drawDiamond(diamond, '#0064ff'));

            // Draw exits
            state.exits.forEach(exit => drawExit(exit));

            // Draw characters
            drawCharacter(state.fireboy, '#ff4500');
            drawCharacter(state.watergirl, '#0064ff');
        }

        // Physics functions
        function checkCollisions(char) {
            let onGround = false;
            let bottom = char.y + char.height;
            let top = char.y;
            let left = char.x;
            let right = char.x + char.width;

            // Check platform collisions
            state.platforms.forEach(platform => {
                if (platform.type === 'moving') {
                    const offsetX = platform.offset;
                    const platformLeft = platform.x + offsetX;
                    const platformRight = platformLeft + platform.width;

                    if (right > platformLeft && left < platformRight) {
                        if (bottom > platform.y && top < platform.y + platform.height) {
                            // Horizontal collision
                            if (char.velocityX > 0) {
                                char.x = platformRight - char.width;
                            } else if (char.velocityX < 0) {
                                char.x = platformLeft;
                            }
                        }

                        if (bottom + 1 > platform.y + platform.height && bottom < platform.y + platform.height + 1 && char.velocityY > 0) {
                            // Landing on platform
                            char.y = platform.y + platform.height - char.height;
                            char.velocityY = 0;
                            onGround = true;
                        }
                    }
                } else if (platform.type === 'tilting') {
                    // Simplified tilting collision
                    const angleRad = platform.angle * Math.PI / 180;
                    const cos = Math.cos(angleRad);
                    const sin = Math.sin(angleRad);

                    const pivotX = platform.pivotX;
                    const pivotY = platform.y + platform.height/2;

                    const relX = char.x - pivotX;
                    const relY = char.y + char.height/2 - pivotY;

                    const dist = Math.sqrt(relX * relX + relY * relY);
                    if (dist < (platform.width/2 + char.width/2)) {
                        const angle = Math.atan2(relY, relX);
                        const platformAngle = Math.atan2(platform.height/2, platform.width/2);

                        if (angle > platformAngle - 0.5 && angle < platformAngle + 0.5) {
                            // Front collision
                            const overlap = dist - (platform.width/2 + char.width/2);
                            const nx = relX - overlap * cos;
                            const ny = relY - overlap * sin;

                            char.x = pivotX + nx;
                            char.y = pivotY - ny + char.height/2;

                            if (bottom + 1 > platform.y && bottom < platform.y + platform.height && char.velocityY > 0) {
                                // Landing on tilting platform
                                char.y = platform.y + platform.height - char.height;
                                char.velocityY = 0;
                                onGround = true;
                            }
                        }
                    }
                } else {
                    const platformLeft = platform.x;
                    const platformRight = platformLeft + platform.width;

                    if (right > platformLeft && left < platformRight) {
                        if (bottom > platform.y && top < platform.y + platform.height) {
                            // Horizontal collision
                            if (char.velocityX > 0) {
                                char.x = platformRight - char.width;
                            } else if (char.velocityX < 0) {
                                char.x = platformLeft;
                            }
                        }

                        if (bottom + 1 > platform.y + platform.height && bottom < platform.y + platform.height + 1 && char.velocityY > 0) {
                            // Landing on platform
                            char.y = platform.y + platform.height - char.height;
                            char.velocityY = 0;
                            onGround = true;
                        }
                    }
                }
            });

            // Check moving barrier
            if (!state.movingBarrier.open) {
                const barrierLeft = state.movingBarrier.x;
                const barrierRight = state.movingBarrier.x + state.movingBarrier.width;

                if (right > barrierLeft && left < barrierRight) {
                    if (bottom > state.movingBarrier.y && top < state.movingBarrier.y + state.movingBarrier.height) {
                        // Horizontal collision
                        if (char.velocityX > 0) {
                            char.x = barrierRight - char.width;
                        } else if (char.velocityX < 0) {
                            char.x = barrierLeft;
                        }
                    }
                }
            }

            // Check pools
            state.poisonPools.forEach(pool => {
                if (bottom > pool.y && top < pool.y + pool.height &&
                    right > pool.x && left < pool.x + pool.width) {
                    if (char === state.fireboy) {
                        state.watergirl.alive = false;
                    } else {
                        state.fireboy.alive = false;
                    }
                }
            });

            state.lavaPools.forEach(pool => {
                if (bottom > pool.y && top < pool.y + pool.height &&
                    right > pool.x && left < pool.x + pool.width) {
                    if (char === state.watergirl) {
                        state.watergirl.alive = false;
                    }
                }
            });

            state.waterPools.forEach(pool => {
                if (bottom > pool.y && top < pool.y + pool.height &&
                    right > pool.x && left < pool.x + pool.width) {
                    if (char === state.fireboy) {
                        state.fireboy.alive = false;
                    }
                }
            });

            // Check exits
            state.exits.forEach(exit => {
                if (bottom > exit.y && top < exit.y + exit.height &&
                    right > exit.x && left < exit.x + exit.width) {
                    if (char === state.fireboy && exit.type === 'fireboy') {
                        state.fireboy.atExit = true;
                    } else if (char === state.watergirl && exit.type === 'watergirl') {
                        state.watergirl.atExit = true;
                    }
                }
            });

            return onGround;
        }

        function checkDiamondCollision(char) {
            const diamonds = char === state.fireboy ? state.diamonds.fb : state.diamonds.wg;
            const bottom = char.y + char.height;
            const top = char.y;
            const left = char.x;
            const right = char.x + char.width;

            for (let i = 0; i < diamonds.length; i++) {
                const diamond = diamonds[i];
                if (!diamond.collected &&
                    bottom > diamond.y && top < diamond.y + diamond.height &&
                    right > diamond.x && left < diamond.x + diamond.width) {
                    diamond.collected = true;
                    return true;
                }
            }
            return false;
        }

        function updateTiltingPlatforms() {
            // Update tilting platforms based on character positions
            const leftPlatform = state.platforms.find(p => p.type === 'tilting' && p.x === 500);
            const rightPlatform = state.platforms.find(p => p.type === 'tilting' && p.x === 1100);

            if (leftPlatform) {
                const fireboyOnLeft = state.fireboy.x + state.fireboy.width/2 > leftPlatform.x &&
                                     state.fireboy.x + state.fireboy.width/2 < leftPlatform.x + leftPlatform.width &&
                                     state.fireboy.y + state.fireboy.height > leftPlatform.y &&
                                     state.fireboy.y < leftPlatform.y + leftPlatform.height;

                const watergirlOnLeft = state.watergirl.x + state.watergirl.width/2 > leftPlatform.x &&
                                       state.watergirl.x + state.watergirl.width/2 < leftPlatform.x + leftPlatform.width &&
                                       state.watergirl.y + state.watergirl.height > leftPlatform.y &&
                                       state.watergirl.y < leftPlatform.y + leftPlatform.height;

                if (fireboyOnLeft || watergirlOnLeft) {
                    // Apply tilt based on character position
                    const centerX = leftPlatform.x + leftPlatform.width/2;
                    const diff = state.fireboy.x + state.fireboy.width/2 + state.watergirl.x + state.watergirl.width/2 - centerX * 2;

                    // Simple tilt based on weight distribution
                    leftPlatform.angle = diff * 0.5;
                } else {
                    leftPlatform.angle = 0;
                }
            }

            if (rightPlatform) {
                const fireboyOnRight = state.fireboy.x + state.fireboy.width/2 > rightPlatform.x &&
                                      state.fireboy.x + state.fireboy.width/2 < rightPlatform.x + rightPlatform.width &&
                                      state.fireboy.y + state.fireboy.height > rightPlatform.y &&
                                      state.fireboy.y < rightPlatform.y + rightPlatform.height;

                const watergirlOnRight = state.watergirl.x + state.watergirl.width/2 > rightPlatform.x &&
                                        state.watergirl.x + state.watergirl.width/2 < rightPlatform.x + rightPlatform.width &&
                                        state.watergirl.y + state.watergirl.height > rightPlatform.y &&
                                        state.watergirl.y < rightPlatform.y + rightPlatform.height;

                if (fireboyOnRight || watergirlOnRight) {
                    const centerX = rightPlatform.x + rightPlatform.width/2;
                    const diff = state.fireboy.x + state.fireboy.width/2 + state.watergirl.x + state.watergirl.width/2 - centerX * 2;

                    // Opposite tilt
                    rightPlatform.angle = diff * -0.5;
                } else {
                    rightPlatform.angle = 0;
                }
            }
        }

        function updateMovingBarrier() {
            // Check if any lower pressure plates are active
            const lowerPlatesActive = state.pressurePlates.some(plate => plate.type === 'lower' && plate.active);

            if (lowerPlatesActive && !state.movingBarrier.open) {
                state.movingBarrier.targetOpen = true;
            } else if (!lowerPlatesActive && state.movingBarrier.open) {
                state.movingBarrier.targetOpen = false;
            }

            // Smooth transition
            if (state.movingBarrier.targetOpen !== state.movingBarrier.open) {
                state.movingBarrier.open = state.movingBarrier.targetOpen;
            }
        }

        function updateMovingPlatforms() {
            const upperPlatesActive = state.pressurePlates.some(plate => plate.type === 'upper' && plate.active);

            // Update moving bridge/platform
            const bridge = state.platforms.find(p => p.type === 'moving' && p.y === 400);
            if (bridge) {
                if (upperPlatesActive) {
                    bridge.offset = bridge.width;
                } else {
                    bridge.offset = 0;
                }
            }
        }

        function updatePressurePlates() {
            state.pressurePlates.forEach(plate => {
                let active = false;

                if (plate.type === 'lower') {
                    active = (state.fireboy.x + state.fireboy.width > plate.x &&
                             state.fireboy.x < plate.x + plate.width &&
                             state.fireboy.y + state.fireboy.height > plate.y &&
                             state.fireboy.y < plate.y + plate.height) ||
                           (state.watergirl.x + state.watergirl.width > plate.x &&
                            state.watergirl.x < plate.x + plate.width &&
                            state.watergirl.y + state.watergirl.height > plate.y &&
                            state.watergirl.y < plate.y + plate.height);
                } else if (plate.type === 'upper') {
                    active = (state.fireboy.x + state.fireboy.width > plate.x &&
                             state.fireboy.x < plate.x + plate.width &&
                             state.fireboy.y + state.fireboy.height > plate.y &&
                             state.fireboy.y < plate.y + plate.height) ||
                           (state.watergirl.x + state.watergirl.width > plate.x &&
